local function stone(x,y,r,mix,water)
  local b=brush{name="st"..x.."_"..y, width=math.max(2,r)}
  b:load{water=water, pigments=mix}
  local pts={{x-r*0.6,y},{x,y-r*0.3},{x+r*0.6,y+r*0.1}}
  b:stroke(pts,{pressure=0.5,duration=0.05})
end
